import { memo, useCallback, useMemo } from "react";
import { Badge, Image } from "@kit/index.js";
import { RemoteComponent, useExperiment, useTranslation } from "travel-platform";
import { useCard } from "./CardContext.js";
import { useCardFragment } from "./fragments.js";
import styles from "./PropertyCard.module.css";

function PhotoCount({ count }) {
    const t = useTranslation();
    return <Badge variant="neutral" className={styles.photoCount}>{t("sr.photos", { count })}</Badge>;
}

function CardImage({ photo, eager }) {
    const square = photo.sizes.find((s) => s.kind === "square240");
    const large = photo.sizes.find((s) => s.kind === "max500");
    const srcSet = useMemo(() => (large ? `${square.url} 240w, ${large.url} 500w` : undefined), [square, large]);
    return <Image src={square.url} srcSet={srcSet} sizes="240px" width={240} height={240} alt={photo.alt.text} placeholderColor={photo.dominantColor} eager={eager} className={styles.image} />;
}

const WishlistSlot = memo(function WishlistSlot({ card, name }) {
    const { trackCard } = useCard();
    const onOpen = useCallback(() => trackCard("card.wishlist"), [trackCard]);
    return (
        <span onClickCapture={onOpen}>
            <RemoteComponent module="wishlist/WishlistButton" props={{ propertyId: card.id, name, saved: card.wishlist.isSaved, a11yLabel: card.wishlist.a11yLabel }} />
        </span>
    );
});

export function CardMedia() {
    const { card, index, trackCard } = useCard();
    const { photos, name } = useCardFragment("PropertyCardBasics", card.basics);
    const tallImage = useExperiment("sr_image_ratio") === 1;
    return (
        <div className={tallImage ? `${styles.media} ${styles.mediaTall}` : styles.media}>
            <a href={card.links.details.href} target={card.links.details.target} rel={card.links.details.rel} className={styles.mediaLink} tabIndex={-1} aria-hidden="true" onClick={() => trackCard("card.photo_click")}>
                <CardImage photo={photos.main} eager={index < 3} />
            </a>
            <WishlistSlot card={card} name={name} />
            <PhotoCount count={photos.count} />
        </div>
    );
}
