import { useMemo } from "react";
import { ErrorBoundary } from "travel-platform";
import { useCard } from "./CardContext.js";

// A part of the card that fails on its own: a broken badge or price block
// leaves the rest of the card in place.
export function CardSection({ name, children }) {
    const { card } = useCard();
    const boundary = useMemo(() => `card-${name}:${card.id}`, [name, card.id]);
    return <ErrorBoundary name={boundary}>{children}</ErrorBoundary>;
}
