import { useState } from "react";
import { Avatar, Inline, ReviewScore, Stack, Text } from "@kit/index.js";
import { useExperiment, useLocalized, useTranslation } from "travel-platform";
import { useCard } from "./CardContext.js";
import { TrackedLink } from "./tracked.js";
import styles from "./PropertyCard.module.css";

function SecondaryScore({ score }) {
    const t = useTranslation();
    const localized = useLocalized();
    return <TrackedLink href="#reviews" variant="small_1" className={styles.secondaryScore} trackingName="card.subscore">{t("sr.subscore", { name: localized(score.name), score: score.formatted })}</TrackedLink>;
}

function SnippetAuthor({ author }) {
    return (
        <Inline as="figcaption" gap={1} className={styles.snippetAuthor}>
            <Avatar name={author.name} initial={author.initial} size="small" />
            <Text as="span" variant="small_1">{author.name}</Text>
            <Text as="span" variant="caption" className={styles.country}>{author.countryCode.toUpperCase()}</Text>
        </Inline>
    );
}

function ReviewSnippet({ snippet }) {
    const t = useTranslation();
    const localized = useLocalized();
    const [expanded, setExpanded] = useState(false);
    const text = localized(snippet.text);
    const long = text.length > 90;
    return (
        <Stack as="figure" gap={1} className={styles.snippet} lang={snippet.language}>
            <Text as="blockquote" variant="small_1" className={styles.snippetText}>"{expanded || !long ? text : `${text.slice(0, 88)}…`}"</Text>
            <SnippetAuthor author={snippet.author} />
            {long ? <button type="button" className={styles.readMore} onClick={() => setExpanded(!expanded)}>{t(expanded ? "sr.read_less" : "sr.read_more")}</button> : null}
        </Stack>
    );
}

export function CardReview() {
    const { card } = useCard();
    const localized = useLocalized();
    const showSnippet = useExperiment("sr_review_snippet") !== 2;
    const review = card.basics.reviewSummary;
    if (!review)
        return null;
    return (
        <Stack gap={1} alignItems="end" className={styles.review} data-testid="review-score">
            <ReviewScore score={review.scoreFormatted} word={localized(review.word)} count={localized(review.countText)} layout="stacked" />
            {review.secondary ? <SecondaryScore score={review.secondary} /> : null}
            {card.reviewSnippet && showSnippet ? <ReviewSnippet snippet={card.reviewSnippet} /> : null}
        </Stack>
    );
}
