import { Icon, Link } from "@kit/index.js";
import { LocalizedText, useTranslation } from "travel-platform";
import styles from "./Results.module.css";

export function Breadcrumbs({ crumbs }) {
    const t = useTranslation();
    return (
        <nav aria-label={t("sr.breadcrumbs")} className={styles.breadcrumbs}>
            <ol className={styles.crumbList}>
                {crumbs.map((crumb, i) => (
                    <li key={i} className={styles.crumb}>
                        {i ? <Icon name="chevron-right" size="smaller" color="alt" /> : null}
                        {crumb.link ? <Link href={crumb.link.href} variant="small_1"><LocalizedText value={crumb.label} /></Link> : <span aria-current="page"><LocalizedText value={crumb.label} /></span>}
                    </li>
                ))}
            </ol>
        </nav>
    );
}
