import styles from "./Avatar.module.css";
import { cx } from "./util.js";

const COLORS = ["teal", "coral", "violet", "green", "amber", "sky"];

export function Avatar({ name, initial, size = "medium" }) {
    const color = COLORS[(name?.charCodeAt(0) ?? 0) % COLORS.length];
    return <span className={cx(styles.avatar, styles[size], styles[color])} aria-hidden="true">{initial ?? name?.[0]}</span>;
}
