import styles from "./Tabs.module.css";
import { Icon } from "./Icon.jsx";
import { cx } from "./util.js";

export function Tabs({ items, selected, variant = "pill", label, onSelect }) {
    return (
        <nav className={cx(styles.tabs, styles[variant])} aria-label={label}>
            <ul className={styles.list}>
                {items.map((item) => (
                    <li key={item.id} className={styles.item}>
                        <a href={item.href} className={cx(styles.tab, item.id === selected && styles.selected)} aria-current={item.id === selected ? "page" : undefined} onClick={onSelect ? (e) => { e.preventDefault(); onSelect(item.id); } : undefined}>
                            {item.icon ? <Icon name={item.icon} size="medium" /> : null}
                            <span>{item.label}</span>
                        </a>
                    </li>
                ))}
            </ul>
        </nav>
    );
}
