// Federated components and lazy boundaries. Remote modules are loaded
// before the page hydrates and kept in a registry, so a RemoteComponent
// renders them synchronously, on the server and on the client alike. Lazy
// (@loadable) components register themselves here, so that the page can
// load every chunk before hydration and steps never wait for the network.
import { Component, createContext, useContext } from "react";
import { tracker } from "./telemetry/tracker.js";

const modules = new Map();
const lazyComponents = [];

export function registerRemoteModule(name, module) {
    modules.set(name, module);
}

export async function loadRemoteModules(loaders) {
    await Promise.all(Object.entries(loaders).map(async ([name, load]) => registerRemoteModule(name, await load())));
}

export function registerLazy(component) {
    lazyComponents.push(component);
    return component;
}

export async function preloadLazy() {
    // Loading a chunk can register more lazy components.
    let loaded = 0;
    while (loaded < lazyComponents.length) {
        const batch = lazyComponents.slice(loaded);
        loaded = lazyComponents.length;
        await Promise.all(batch.map((component) => component.load()));
    }
}

const RemoteScopeContext = createContext(null);

export function useRemoteScope() {
    return useContext(RemoteScopeContext);
}

export class ErrorBoundary extends Component {
    constructor(props) {
        super(props);
        this.state = { error: null };
    }

    static getDerivedStateFromError(error) {
        return { error };
    }

    componentDidCatch(error) {
        tracker.push("sink", "error", { boundary: this.props.name, message: String(error?.message ?? error) });
    }

    render() {
        if (this.state.error)
            return this.props.fallback ?? null;
        return this.props.children;
    }
}

export class RemoteComponent extends Component {
    render() {
        const { module, exportName = "default", fallback = null, props } = this.props;
        const loaded = modules.get(module);
        if (!loaded)
            return fallback;
        const Exported = loaded[exportName];
        const remote = module.split("/")[0];
        return (
            <RemoteScopeContext.Provider value={remote}>
                <ErrorBoundary name={module} fallback={fallback}>
                    <Exported {...props} />
                </ErrorBoundary>
            </RemoteScopeContext.Provider>
        );
    }
}
