// The property page's GraphQL documents: PropertyPage feeds the two React
// islands from the inline snapshot, PropertyReviews is fetched by the reviews
// island once it has hydrated.
import { LOCALIZED } from "./search.mjs";

export const PROPERTY_PAGE = `
query PropertyPage($id: ID!, $dates: DatesInput!, $occupancy: OccupancyInput!) {
  property(id: $id) {
    id
    name
    starRating { value isEstimated a11yLabel { ...LocalizedStringFields } }
    reviewSummary {
      score
      scoreFormatted
      word { ...LocalizedTextFields }
      count
      countText { ...LocalizedTextFields }
      subscores { key name { ...LocalizedStringFields } value formatted highlighted }
      topics { id label { ...LocalizedTextFields } mentions }
    }
    wishlist { isSaved listId a11yLabel { ...LocalizedStringFields } }
    share { link { ...LinkFields } title { ...LocalizedStringFields } }
    priceMatch { text { ...LocalizedTextFields } }
    facilities {
      popular { id text { ...LocalizedTextFields } icon { ...IconFields } }
      groups { id title { ...LocalizedTextFields } icon { ...IconFields } items { id text { ...LocalizedTextFields } paid } }
    }
    highlights {
      title { ...LocalizedTextFields }
      items { id title { ...LocalizedTextFields } body { ...LocalizedTextFields } icon { ...IconFields } }
      breakfast { text { ...LocalizedTextFields } }
      parking { text { ...LocalizedTextFields } }
      cta { label { ...LocalizedStringFields } }
    }
    location { district { id name { ...LocalizedTextFields } score } scoreText { ...LocalizedTextFields } }
    tracking { ...ExperimentFields }
  }
}
${LOCALIZED}`;

export const PROPERTY_REVIEWS = `
query PropertyReviews($id: ID!, $page: Int!, $pageSize: Int!, $sort: ReviewSort!) {
  propertyReviews(id: $id, page: $page, pageSize: $pageSize, sort: $sort) {
    totalCount
    reviews {
      id
      author { name countryCode initial travellerType { ...LocalizedStringFields } }
      score
      scoreFormatted
      title { ...LocalizedTextFields }
      positive { ...LocalizedTextFields }
      negative { ...LocalizedTextFields }
      stayed { roomName nights month { ...LocalizedStringFields } }
      language
      helpfulVotes
    }
  }
}
${LOCALIZED}`;
