import { memo, useMemo } from "react";
import { addMonths, useDateFormat } from "travel-platform";
import styles from "./Calendar.module.css";
import { IconButton } from "./Button.jsx";
import { cx } from "./util.js";

const WEEKDAY_SAMPLE = ["2026-11-02", "2026-11-03", "2026-11-04", "2026-11-05", "2026-11-06", "2026-11-07", "2026-11-08"];

function monthDays(month) {
    const first = new Date(`${month}-01T00:00:00Z`);
    const offset = (first.getUTCDay() + 6) % 7;
    const days = [];
    for (let i = 0; i < offset; i++)
        days.push(null);
    const date = new Date(first);
    while (date.getUTCMonth() === first.getUTCMonth()) {
        days.push(date.toISOString().slice(0, 10));
        date.setUTCDate(date.getUTCDate() + 1);
    }
    return days;
}

const CalendarDay = memo(function CalendarDay({ day, state, label, onSelect }) {
    return (
        <td role="gridcell" className={styles.cell} aria-selected={state === "start" || state === "end"}>
            <button
                type="button"
                className={cx(styles.day, styles[state])}
                disabled={state === "disabled"}
                aria-label={label}
                data-date={day}
                onClick={() => onSelect(day)}
            >
                {Number(day.slice(8))}
            </button>
        </td>
    );
});

function dayState(day, today, checkin, checkout) {
    if (day < today)
        return "disabled";
    if (day === checkin)
        return "start";
    if (day === checkout)
        return "end";
    if (checkin && checkout && day > checkin && day < checkout)
        return "inRange";
    if (day === today)
        return "today";
    return "default";
}

function CalendarMonth({ month, today, checkin, checkout, onSelect }) {
    const formatMonth = useDateFormat({ month: "long", year: "numeric" });
    const formatDay = useDateFormat({ weekday: "long", day: "numeric", month: "long", year: "numeric" });
    const formatWeekday = useDateFormat({ weekday: "short" });
    const days = useMemo(() => monthDays(month), [month]);
    const weeks = [];
    for (let i = 0; i < days.length; i += 7)
        weeks.push(days.slice(i, i + 7));
    return (
        <div className={styles.month}>
            <h3 className={styles.monthTitle} aria-live="polite">{formatMonth(`${month}-01`)}</h3>
            <table role="grid" className={styles.grid}>
                <thead>
                    <tr>{WEEKDAY_SAMPLE.map((day) => <th key={day} scope="col" className={styles.weekday}>{formatWeekday(day).slice(0, 2)}</th>)}</tr>
                </thead>
                <tbody>
                    {weeks.map((week, w) => (
                        <tr key={w}>
                            {week.map((day, d) => (day ? <CalendarDay key={day} day={day} state={dayState(day, today, checkin, checkout)} label={formatDay(day)} onSelect={onSelect} /> : <td key={`e${d}`} className={styles.cell} />))}
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
}

export function Calendar({ month, today, checkin, checkout, onSelect, onMonthChange, labels, testId }) {
    const minMonth = today.slice(0, 7);
    return (
        <div className={styles.calendar} data-testid={testId}>
            <IconButton icon="chevron-left" label={labels.previous} className={cx(styles.nav, styles.previous)} disabled={month <= minMonth} onClick={() => onMonthChange(addMonths(month, -1))} data-testid={testId && `${testId}-previous`} />
            <IconButton icon="chevron-right" label={labels.next} className={cx(styles.nav, styles.next)} onClick={() => onMonthChange(addMonths(month, 1))} data-testid={testId && `${testId}-next`} />
            <div className={styles.months}>
                <CalendarMonth month={month} today={today} checkin={checkin} checkout={checkout} onSelect={onSelect} />
                <CalendarMonth month={addMonths(month, 1)} today={today} checkin={checkin} checkout={checkout} onSelect={onSelect} />
            </div>
        </div>
    );
}
