// A small translation runtime modelled on the reference site's: each
// micro-frontend registers its catalog of message keys, messages can have
// plural forms and {placeholders}, and API text arrives as LocalizedString
// tags ({ key, text }) that are looked up by key with the server's text as
// the fallback.

const messages = new Map();
const pluralRules = new Map();
const compiled = new Map();

// Catalogs arrive with each micro-frontend's chunks; components that
// translate subscribe to the catalog version so that they re-render when
// the strings they need show up.
let version = 0;
const listeners = new Set();

export function registerCatalog(namespace, catalog) {
    for (const [key, message] of Object.entries(catalog))
        messages.set(key, message);
    version++;
    for (const listener of listeners)
        listener();
    return namespace;
}

export function subscribeCatalogs(listener) {
    listeners.add(listener);
    return () => listeners.delete(listener);
}

export function catalogVersion() {
    return version;
}

export function hasMessage(key) {
    return messages.has(key);
}

function rulesFor(locale) {
    let rules = pluralRules.get(locale);
    if (!rules) {
        rules = new Intl.PluralRules(locale);
        pluralRules.set(locale, rules);
    }
    return rules;
}

// Splits "a {name} b" into ["a ", { name }, " b"] once per message.
function compile(message) {
    let parts = compiled.get(message);
    if (!parts) {
        parts = [];
        const pattern = /\{(\w+)\}/g;
        let last = 0;
        for (let match; (match = pattern.exec(message));) {
            if (match.index > last)
                parts.push(message.slice(last, match.index));
            parts.push({ name: match[1] });
            last = match.index + match[0].length;
        }
        if (last < message.length)
            parts.push(message.slice(last));
        compiled.set(message, parts);
    }
    return parts;
}

function interpolate(message, params) {
    let result = "";
    for (const part of compile(message))
        result += typeof part === "string" ? part : String(params?.[part.name] ?? "");
    return result;
}

export function translate(locale, key, params) {
    let message = messages.get(key);
    if (message === undefined)
        return key;
    if (typeof message === "object") {
        const count = params?.count ?? 0;
        message = message[count === 0 && message.zero ? "zero" : rulesFor(locale).select(count)] ?? message.other;
    }
    return params ? interpolate(message, params) : message;
}

export function resolveTag(tag) {
    if (!tag)
        return "";
    const message = messages.get(tag.key);
    return typeof message === "string" && !message.includes("{") ? message : tag.text;
}

// A LocalizedText is { text, tag: LocalizedString }.
export function resolveText(text) {
    if (!text)
        return "";
    return text.tag ? resolveTag(text.tag) || text.text : text.text;
}
