import { useCallback, useMemo } from "react";
import { Pagination, Text } from "@kit/index.js";
import { Translate, useSearchState, useTrack, useTranslation } from "travel-platform";
import { useResults } from "./ResultsContext.js";
import styles from "./Results.module.css";

export function ResultsPagination() {
    const t = useTranslation();
    const track = useTrack();
    const { result } = useResults();
    const { navigate, displayState } = useSearchState();
    const labels = useMemo(() => ({ nav: t("sr.pagination"), previous: t("sr.previous_page"), next: t("sr.next_page"), page: (page) => t("sr.page", { page }) }), [t]);
    const onChange = useCallback((page) => {
        track("results.page_changed", { page });
        navigate((state) => ({ ...state, page }), "pagination");
    }, [navigate, track]);
    if (!result || result.pagination.pageCount < 2)
        return null;
    const { offset, rowsPerPage } = result.pagination;
    return (
        <div className={styles.pagination}>
            <Pagination page={displayState.page} pageCount={result.pagination.pageCount} onChange={onChange} labels={labels} testId="pagination" />
            <Text variant="small_1" color="alt" align="center">{t("sr.showing", { from: offset + 1, to: Math.min(offset + rowsPerPage, result.meta.totalCount) })}</Text>
            <Text variant="small_1" color="alt" align="center"><Translate id="sr.prices_info" /></Text>
        </div>
    );
}
