import styles from "./Pagination.module.css";
import { IconButton } from "./Button.jsx";
import { cx } from "./util.js";

function visiblePages(page, count) {
    const pages = new Set([0, count - 1, page - 1, page, page + 1]);
    if (page < 4)
        [1, 2, 3, 4].forEach((p) => pages.add(p));
    return [...pages].filter((p) => p >= 0 && p < count).sort((a, b) => a - b);
}

export function Pagination({ page, pageCount, onChange, labels, testId }) {
    const pages = visiblePages(page, pageCount);
    const items = [];
    let previous = -1;
    for (const p of pages) {
        if (p - previous > 1)
            items.push(<li key={`gap${p}`} className={styles.gap} aria-hidden="true">…</li>);
        items.push(
            <li key={p} className={styles.item}>
                <button type="button" className={cx(styles.page, p === page && styles.current)} aria-current={p === page ? "page" : undefined} aria-label={labels.page(p + 1)} onClick={() => onChange(p)} data-page={p}>
                    {p + 1}
                </button>
            </li>,
        );
        previous = p;
    }
    return (
        <nav className={styles.pagination} aria-label={labels.nav} data-testid={testId}>
            <IconButton icon="chevron-left" label={labels.previous} disabled={page === 0} onClick={() => onChange(page - 1)} />
            <ol className={styles.list}>{items}</ol>
            <IconButton icon="chevron-right" label={labels.next} disabled={page >= pageCount - 1} onClick={() => onChange(page + 1)} />
        </nav>
    );
}
