// React bindings of the tracker: a tracking context that carries the
// surface a component lives in, impression tracking through one shared
// IntersectionObserver, and experiment exposure logging for the
// ExperimentTracking objects the API sends.
import { createContext, useCallback, useContext, useEffect, useLayoutEffect, useMemo, useRef } from "react";
import { isServer } from "../env.js";
import { tracker } from "./tracker.js";

const TrackingContext = createContext({ surface: "page", path: [] });

export function TrackingScope({ surface, children }) {
    const parent = useContext(TrackingContext);
    const value = useMemo(() => ({ surface, path: [...parent.path, surface] }), [parent, surface]);
    return <TrackingContext.Provider value={value}>{children}</TrackingContext.Provider>;
}

const useIsomorphicLayoutEffect = isServer ? useEffect : useLayoutEffect;

// A stable tracking callback that always reports the latest scope.
export function useTrack() {
    const scope = useContext(TrackingContext);
    const latest = useRef(scope);
    useIsomorphicLayoutEffect(() => {
        latest.current = scope;
    });
    return useCallback((name, payload) => tracker.track(name, { surface: latest.current.surface, path: latest.current.path.join("/"), ...payload }), []);
}

let observer = null;
const impressionPayloads = new WeakMap();
const seenImpressions = new Set();

function impressionObserver() {
    if (!observer && !isServer && typeof IntersectionObserver !== "undefined") {
        observer = new IntersectionObserver((entries) => {
            for (const entry of entries) {
                if (!entry.isIntersecting)
                    continue;
                const payload = impressionPayloads.get(entry.target);
                if (payload && !seenImpressions.has(payload.key)) {
                    seenImpressions.add(payload.key);
                    tracker.track("impression", payload);
                }
            }
        }, { threshold: 0.5 });
    }
    return observer;
}

// Observes the element in `ref` for an impression with `payload`; `key` must
// be unique per impression.
export function useImpression(ref, key, payload) {
    const scope = useContext(TrackingContext);
    const latest = useRef(payload);
    latest.current = payload;
    useEffect(() => {
        const element = ref.current;
        const io = impressionObserver();
        if (!element || !io)
            return undefined;
        impressionPayloads.set(element, { key, surface: scope.surface, ...latest.current });
        io.observe(element);
        return () => io.unobserve(element);
    }, [ref, key, scope]);
}

const ExperimentContext = createContext(null);

export function ExperimentProvider({ assignments, children }) {
    const value = useMemo(() => ({ assignments: new Map(Object.entries(assignments ?? {})), exposed: new Set() }), [assignments]);
    return <ExperimentContext.Provider value={value}>{children}</ExperimentContext.Provider>;
}

// The variant of an experiment; reading it counts as an exposure.
export function useExperiment(tag) {
    const context = useContext(ExperimentContext);
    const variant = useMemo(() => context?.assignments.get(tag) ?? 0, [context, tag]);
    useEffect(() => {
        if (!context || context.exposed.has(tag))
            return;
        context.exposed.add(tag);
        tracker.push("exposed", "exposure", { tags: [`${tag}:read:${variant}`] });
    }, [context, tag, variant]);
    return variant;
}

// Logs exposure of the experiments in `tracking` (a list of
// ExperimentTracking objects) once the component has committed.
export function useExperimentTracking(tracking) {
    const context = useContext(ExperimentContext);
    const tags = useMemo(() => (tracking ?? []).filter((t) => t.trackOn === "VIEW").map((t) => `${t.tag}:${t.stage}:${t.variant}`), [tracking]);
    useEffect(() => {
        if (!context)
            return;
        const fresh = tags.filter((tag) => !context.exposed.has(tag));
        if (!fresh.length)
            return;
        for (const tag of fresh)
            context.exposed.add(tag);
        tracker.push("exposed", "exposure", { tags: fresh });
    }, [context, tags]);
}
