import { memo, useMemo, useRef } from "react";
import { Accordion, Card, Grid, Image, Inline, ReviewScore, Stack, Text, Title } from "@kit/index.js";
import { LocalizedText, TrackingScope, Translate, useImpression, useLocalized, useNumberFormat } from "travel-platform";
import { TrackedLink } from "../card/tracked.js";
import { useResults } from "./ResultsContext.js";
import styles from "./BelowResults.module.css";

const Favourite = memo(function Favourite({ card }) {
    const localized = useLocalized();
    const photo = card.basics.photos.main.sizes[0];
    const review = card.basics.reviewSummary;
    return (
        <Card as="li" variant="outlined" padding={false} className={styles.favourite}>
            <Image src={photo.url} width={photo.width} height={photo.height} alt={card.basics.photos.main.alt.text} ratio="4 / 3" />
            <Stack gap={1} className={styles.favouriteBody}>
                <TrackedLink href={card.links.details.href} variant="strong_2" trackingName="favourites.property">{card.basics.name}</TrackedLink>
                <Text variant="small_1" color="alt"><LocalizedText value={card.basics.location.district.name} /></Text>
                {review ? <ReviewScore score={review.scoreFormatted} word={localized(review.word)} size="small" /> : null}
            </Stack>
        </Card>
    );
});

function GuestFavourites({ cards, city }) {
    const ref = useRef(null);
    useImpression(ref, `favourites:${city}`, { section: "favourites" });
    const favourites = useMemo(() => cards.filter((card) => card.basics.reviewSummary?.score >= 8.5).slice(0, 6), [cards]);
    if (!favourites.length)
        return null;
    return (
        <section ref={ref} className={styles.section}>
            <Title variant="headline_3" subtitle={<Translate id="sr.favourites_subtitle" />}><Translate id="sr.favourites" /></Title>
            <ul className={styles.favourites}>{favourites.map((card) => <Favourite key={card.id} card={card} />)}</ul>
        </section>
    );
}

const Destination = memo(function Destination({ destination }) {
    const format = useNumberFormat();
    return (
        <li className={styles.destination}>
            <span className={styles.destinationIcon} aria-hidden="true">{destination.name[0]}</span>
            <Stack gap={0}>
                <TrackedLink href={`city/${destination.id}.html`} variant="strong_2" trackingName="nearby.destination">{destination.name}</TrackedLink>
                <Text variant="small_1" color="alt"><Translate id="sr.nearby_properties" params={{ count: format(destination.count) }} /></Text>
            </Stack>
        </li>
    );
});

function NearbyDestinations({ destinations }) {
    return (
        <section className={styles.section}>
            <Title variant="headline_3"><Translate id="sr.nearby" /></Title>
            <Grid columns={{ base: 2, large: 4 }} gap={3} className={styles.destinations}>
                {destinations.map((destination) => <Destination key={destination.id} destination={destination} />)}
            </Grid>
        </section>
    );
}

function CityFaq({ faq }) {
    return (
        <section className={styles.section}>
            <Title variant="headline_3"><Translate id="sr.faq" /></Title>
            <Stack gap={0}>
                {faq.map((item, i) => (
                    <Accordion key={i} title={item.question} defaultOpen={false}>
                        <Text variant="body_2">{item.answer}</Text>
                    </Accordion>
                ))}
            </Stack>
        </section>
    );
}

export function BelowResults({ config }) {
    const { result } = useResults();
    if (!result)
        return null;
    return (
        <TrackingScope surface="below-results">
            <Stack gap={6} className={styles.below}>
                <GuestFavourites cards={result.results} city={result.meta.destination.id} />
                <NearbyDestinations destinations={config.nearbyDestinations} />
                <CityFaq faq={config.faq} />
                <Inline gap={2}><Text variant="small_1" color="alt"><Translate id="sr.travel_advice" /></Text></Inline>
            </Stack>
        </TrackingScope>
    );
}
