import { Banner } from "@kit/index.js";
import { LocalizedText } from "travel-platform";
import { useResults } from "./ResultsContext.js";

export function SearchMessages() {
    const { result } = useResults();
    if (!result?.messages.length)
        return null;
    return result.messages.map((message) => <Banner key={message.id} variant="neutral" icon="info"><LocalizedText value={message.text} /></Banner>);
}
