import { Badge, Tooltip } from "@kit/index.js";
import { LocalizedText, useExperiment, useLocalized } from "travel-platform";
import { useCard } from "./CardContext.js";
import { useCardFragment } from "./fragments.js";
import styles from "./PropertyCard.module.css";

const VARIANTS = { CONSTRUCTIVE: "constructive", DESTRUCTIVE: "destructive", NEUTRAL: "neutral", BRAND: "brand" };

function DealBadge({ badge }) {
    const localized = useLocalized();
    return (
        <Tooltip text={localized(badge.tooltip.body)}>
            <Badge variant={VARIANTS[badge.style.variant]} emphasis={badge.style.emphasis === "STRONG" ? "strong" : "subtle"} tabIndex={0}><LocalizedText value={badge.text} /></Badge>
        </Tooltip>
    );
}

function QualityBadge({ badge }) {
    const localized = useLocalized();
    return <Badge variant="brand" icon={badge.icon.name} title={localized(badge.tooltip.body)}><LocalizedText value={badge.text} /></Badge>;
}

function SustainabilityBadge({ badge }) {
    const localized = useLocalized();
    const contrast = useExperiment("sr_badge_contrast");
    return <Badge variant={contrast ? "constructive" : "outline"} icon={badge.icon.name} title={localized(badge.tooltip.body)}><LocalizedText value={badge.text} /></Badge>;
}

function ScarcityBadge({ badge }) {
    const localized = useLocalized();
    return <Badge variant="destructive" emphasis="subtle"><LocalizedText value={badge.text} /></Badge>;
}

const BADGES = { DealBadge, QualityBadge, SustainabilityBadge, ScarcityBadge };

function CardBadge({ badge: fromList }) {
    const badge = useCardFragment("CardBadgeFields", fromList);
    const Component = BADGES[badge.__typename];
    return <Component badge={badge} />;
}

export function CardBadges() {
    const { card } = useCard();
    if (!card.badges.length)
        return null;
    return (
        <ul className={styles.badges}>
            {card.badges.map((badge) => {
                return <li key={badge.id} className={styles.badgeItem}><CardBadge badge={badge} /></li>;
            })}
        </ul>
    );
}
