import { useCallback, useEffect, useRef, useState } from "react";
import styles from "./Slider.module.css";
import { cx } from "./util.js";

const KEY_STEPS = { ArrowLeft: -1, ArrowDown: -1, ArrowRight: 1, ArrowUp: 1, PageDown: -10, PageUp: 10 };

function Thumb({ value, min, max, position, label, valueText, onStep, onJump, testId }) {
    const onKeyDown = useCallback((event) => {
        if (event.key in KEY_STEPS) {
            event.preventDefault();
            onStep(KEY_STEPS[event.key]);
        } else if (event.key === "Home" || event.key === "End") {
            event.preventDefault();
            onJump(event.key === "Home" ? min : max);
        }
    }, [onStep, onJump, min, max]);
    return (
        <div
            role="slider"
            tabIndex={0}
            className={styles.thumb}
            style={{ "--tk_slider-position": `${position}%` }}
            aria-label={label}
            aria-valuemin={min}
            aria-valuemax={max}
            aria-valuenow={value}
            aria-valuetext={valueText}
            onKeyDown={onKeyDown}
            data-testid={testId}
        />
    );
}

// A two-thumb range slider. `onChange` gets every step, `onCommit` is meant
// for the (debounced) action that applies the range.
export function RangeSlider({ min, max, step, value, onChange, labels, formatValue, histogram, className, testId }) {
    const [range, setRange] = useState(value);
    const trackRef = useRef(null);
    const widthRef = useRef(0);
    useEffect(() => setRange(value), [value[0], value[1]]);
    useEffect(() => {
        const track = trackRef.current;
        if (!track || typeof ResizeObserver === "undefined")
            return undefined;
        const observer = new ResizeObserver(([entry]) => {
            widthRef.current = entry.contentRect.width;
        });
        observer.observe(track);
        return () => observer.disconnect();
    }, []);
    const update = useCallback((index, next) => {
        const result = [...range];
        const clamped = Math.min(max, Math.max(min, next));
        result[index] = index === 0 ? Math.min(clamped, range[1] - step) : Math.max(clamped, range[0] + step);
        setRange(result);
        onChange?.(result);
    }, [range, min, max, step, onChange]);
    const percent = (v) => ((v - min) / (max - min)) * 100;
    const highest = histogram ? Math.max(1, ...histogram.map((bar) => bar.count)) : 1;
    return (
        <div className={cx(styles.slider, className)} data-testid={testId}>
            {histogram ? (
                <div className={styles.histogram} aria-hidden="true">
                    {histogram.map((bar) => (
                        <span key={bar.from} className={cx(styles.bar, bar.from >= range[0] && bar.to <= range[1] && styles.active)} style={{ "--tk_bar-height": `${Math.round((bar.count / highest) * 100)}%` }} />
                    ))}
                </div>
            ) : null}
            <div ref={trackRef} className={styles.track}>
                <div className={styles.range} style={{ "--tk_slider-start": `${percent(range[0])}%`, "--tk_slider-end": `${100 - percent(range[1])}%` }} />
                <Thumb value={range[0]} min={min} max={max} position={percent(range[0])} label={labels.min} valueText={formatValue(range[0])} onStep={(d) => update(0, range[0] + d * step)} onJump={(v) => update(0, v)} testId={testId && `${testId}-min`} />
                <Thumb value={range[1]} min={min} max={max} position={percent(range[1])} label={labels.max} valueText={formatValue(range[1])} onStep={(d) => update(1, range[1] + d * step)} onJump={(v) => update(1, v)} testId={testId && `${testId}-max`} />
            </div>
            <div className={styles.values}>
                <span>{formatValue(range[0])}</span>
                <span>{range[1] >= max ? `${formatValue(range[1])}+` : formatValue(range[1])}</span>
            </div>
        </div>
    );
}
