import { memo } from "react";
import { Badge, Inline, Price, Stack, Text } from "@kit/index.js";
import { LocalizedText, useExperiment, useLocalized } from "travel-platform";
import { useCard } from "./CardContext.js";
import styles from "./PropertyCard.module.css";

const Discount = memo(function Discount({ discount }) {
    const localized = useLocalized();
    return <Badge variant="constructive" emphasis="strong" title={localized(discount.tooltip)}><LocalizedText value={discount.label} /></Badge>;
});

function NightsAndGuests({ text }) {
    const localized = useLocalized();
    return <Text variant="small_1" color="alt" className={styles.nights}>{localized(text)}</Text>;
}

function TaxesLine({ text }) {
    const localized = useLocalized();
    return <Text variant="small_1" color="alt" data-testid="taxes-and-charges">{localized(text)}</Text>;
}

export function CardPrice() {
    const { card } = useCard();
    const localized = useLocalized();
    const compact = useExperiment("sr_card_price_layout") === 1;
    const price = card.priceDisplay;
    return (
        <Stack gap={compact ? 0 : 1} alignItems="end" className={styles.price} data-testid="availability-rate-information">
            {price.discounts.length ? <Inline gap={1} className={styles.discounts}>{price.discounts.map((discount) => <Discount key={discount.kind} discount={discount} />)}</Inline> : null}
            <NightsAndGuests text={price.nightsAndGuests} />
            <Price amount={price.display.amountRounded} strikethrough={price.strikethrough?.amountRounded} label={localized(price.a11yLabel)} testId="price-and-discounted-price" />
            <TaxesLine text={price.taxesLine} />
        </Stack>
    );
}
