// The page-level contexts every micro-frontend reads: feature flags, the
// (logged-out) user, the viewport class, the layer that popovers portal
// into, and the polite live region.
import { createContext, useCallback, useContext, useMemo, useState } from "react";

const FeatureFlagsContext = createContext({});
const UserContext = createContext({ loggedIn: false });
const ViewportContext = createContext({ kind: "desktop", width: 1440 });
const LayerContext = createContext(null);
const AnnouncerContext = createContext(() => {});
const PageContext = createContext({ pageName: "searchresults" });

export function FeatureFlagsProvider({ flags, children }) {
    return <FeatureFlagsContext.Provider value={flags}>{children}</FeatureFlagsContext.Provider>;
}

export function useFeatureFlag(name) {
    return Boolean(useContext(FeatureFlagsContext)[name]);
}

export function UserProvider({ user, children }) {
    return <UserContext.Provider value={user}>{children}</UserContext.Provider>;
}

export function useUser() {
    return useContext(UserContext);
}

export function ViewportProvider({ viewport, children }) {
    return <ViewportContext.Provider value={viewport}>{children}</ViewportContext.Provider>;
}

export function useViewport() {
    return useContext(ViewportContext);
}

export function PageProvider({ page, children }) {
    return <PageContext.Provider value={page}>{children}</PageContext.Provider>;
}

export function usePage() {
    return useContext(PageContext);
}

// `getContainer` returns the element popovers and dialogs portal into.
export function LayerProvider({ getContainer, children }) {
    const [stack, setStack] = useState([]);
    const push = useCallback((id) => setStack((s) => [...s, id]), []);
    const pop = useCallback((id) => setStack((s) => s.filter((x) => x !== id)), []);
    const value = useMemo(() => ({ getContainer, stack, push, pop }), [getContainer, stack, push, pop]);
    return <LayerContext.Provider value={value}>{children}</LayerContext.Provider>;
}

export function useLayer() {
    return useContext(LayerContext);
}

export function AnnouncerProvider({ children }) {
    const [message, setMessage] = useState("");
    const announce = useCallback((text) => setMessage(text), []);
    return (
        <AnnouncerContext.Provider value={announce}>
            {children}
            <div aria-live="polite" role="status" className="travel-announcer">{message}</div>
        </AnnouncerContext.Provider>
    );
}

export function useAnnounce() {
    return useContext(AnnouncerContext);
}
