import { useEffect, useMemo, useRef } from "react";
import { gql, useQuery } from "@apollo/client";
import { RemoteComponent, emitStepEvent, startSpan, useAnnounce, useSearchState, useTranslation } from "travel-platform";
import { PROPERTY_SEARCH } from "../../graphql/search.mjs";
import { searchVariables } from "../../shared/search-input.mjs";
import { Breadcrumbs } from "./Breadcrumbs.jsx";
import { ResultsHeader } from "./ResultsHeader.jsx";
import { ResultsList } from "./ResultsList.jsx";
import { ResultsPagination } from "./ResultsPagination.jsx";
import { SearchMessages } from "./SearchMessages.jsx";
import { ResultsContext } from "./ResultsContext.js";
import { BelowResults } from "./BelowResults.jsx";
import styles from "./SearchResultsPage.module.css";

export const PROPERTY_SEARCH_QUERY = gql(PROPERTY_SEARCH);

function useSearch() {
    const { state, isPending } = useSearchState();
    const variables = useMemo(() => searchVariables(state), [state]);
    const { data, previousData, loading } = useQuery(PROPERTY_SEARCH_QUERY, { variables });
    const result = (data ?? previousData)?.accommodationSearch ?? null;
    return { result, loading: loading || isPending, state };
}

// Reports when the results of the current search have committed: the end of
// every search-type benchmark step.
function useSettled(result, loading) {
    const announce = useAnnounce();
    const t = useTranslation();
    const span = useRef(null);
    if (loading && !span.current)
        span.current = startSpan("searchresults.update");
    useEffect(() => {
        if (loading || !result)
            return;
        span.current?.setAttribute("results", result.results.length).end();
        span.current = null;
        announce(t("sr.found", { count: result.meta.totalCount }));
        emitStepEvent("results-settled", { searchId: result.searchId });
    }, [result, loading, announce, t]);
}

export function SearchResultsPage({ config }) {
    const { result, loading } = useSearch();
    useSettled(result, loading);
    const value = useMemo(() => ({ result, loading }), [result, loading]);
    return (
        <ResultsContext.Provider value={value}>
            <div className={styles.page}>
                <RemoteComponent module="headerShell/Header" props={{ product: "stays" }} />
                <div className={styles.searchboxBand}>
                    <div className={styles.searchboxInner}>
                        <RemoteComponent module="searchbox/SearchBox" props={{ destinationName: result?.meta.destination.name ?? config.destinationName, trending: config.nearbyDestinations.slice(0, 8) }} />
                    </div>
                </div>
                <main className={styles.main}>
                    {result ? <Breadcrumbs crumbs={result.meta.breadcrumbs} /> : null}
                    <div className={styles.columns}>
                        <div className={styles.sidebar}>
                            <RemoteComponent module="filters/FilterPanel" props={{ groups: result?.filters, mapPreview: result?.mapPreview, loading }} />
                        </div>
                        <div className={styles.content} data-testid="results-column">
                            <ResultsHeader />
                            <SearchMessages />
                            <ResultsList />
                            <ResultsPagination />
                            <BelowResults config={config} />
                        </div>
                    </div>
                </main>
                <RemoteComponent module="headerShell/Footer" props={{ destinations: config.footerDestinations, year: 2026 }} />
                <RemoteComponent module="trackers/PageTrackers" />
                <RemoteComponent module="trackers/AdSlots" props={{ count: config.inertFrames }} />
            </div>
        </ResultsContext.Provider>
    );
}
