import { gql, useFragment } from "@apollo/client";
import { LOCALIZED, PROPERTY_CARD } from "../../graphql/search.mjs";

const CARD_FRAGMENTS = gql(PROPERTY_CARD + LOCALIZED);

// Reads a part of a card from the cache through one of the card's
// fragments, as the card's components read their data on the reference
// site. Falls back to the object passed down while the cache doesn't have
// it complete.
export function useCardFragment(fragmentName, from) {
    const { data, complete } = useFragment({ fragment: CARD_FRAGMENTS, fragmentName, from });
    return complete ? data : from;
}
