import { Translate, useExperiment } from "travel-platform";
import { useCard } from "./CardContext.js";
import { useOpenProperty } from "../navigation.js";
import { TrackedButton } from "./tracked.js";
import styles from "./PropertyCard.module.css";

export function CardCta() {
    const { card, trackCard } = useCard();
    const openProperty = useOpenProperty();
    const wide = useExperiment("sr_card_cta_copy") === 1;
    const { availability } = card.links;
    return (
        <TrackedButton
            href={availability.href}
            target={availability.target}
            rel={availability.rel}
            icon="chevron-right"
            iconPosition="end"
            wide={wide}
            className={styles.cta}
            trackingName="card.cta"
            trackingData={{ position: card.position }}
            onClick={(e) => {
                trackCard("card.cta_click");
                openProperty(e, card.id);
            }}
            data-testid="availability-cta-btn"
        >
            <Translate id="sr.see_availability" />
        </TrackedButton>
    );
}
