import { useMoneyFormat } from "travel-platform";
import styles from "./Price.module.css";
import { cx } from "./util.js";

function PriceStrikethrough({ amount }) {
    const format = useMoneyFormat();
    return <span className={styles.strikethrough} suppressHydrationWarning>{format(amount)}</span>;
}

function PriceAmount({ amount }) {
    const format = useMoneyFormat();
    return <span className={styles.amount} suppressHydrationWarning>{format(amount)}</span>;
}

export function Price({ amount, strikethrough, size = "large", label, className, testId }) {
    return (
        <div className={cx(styles.price, styles[size], className)} aria-label={label} data-testid={testId}>
            {strikethrough ? <PriceStrikethrough amount={strikethrough} /> : null}
            <PriceAmount amount={amount} />
        </div>
    );
}
