import styles from "./Skeleton.module.css";
import { cx } from "./util.js";

export function Skeleton({ width = "100%", height = 16, radius, className }) {
    return <span aria-hidden="true" className={cx(styles.skeleton, radius === "full" && styles.round, className)} style={{ "--tk_skeleton-width": typeof width === "number" ? `${width}px` : width, "--tk_skeleton-height": `${height}px` }} />;
}

export function SkeletonText({ lines = 3, className }) {
    const rows = [];
    for (let i = 0; i < lines; i++)
        rows.push(<Skeleton key={i} width={i === lines - 1 ? "60%" : "100%"} height={12} />);
    return <span className={cx(styles.text, className)}>{rows}</span>;
}
