import { useCallback, useMemo, useRef, useState } from "react";
import { Icon, ListMenu, Popover } from "@kit/index.js";
import { useLocalized, useSearchState, useTrack, useTranslation } from "travel-platform";
import styles from "./Results.module.css";

export function SortBar({ sorters }) {
    const t = useTranslation();
    const localized = useLocalized();
    const track = useTrack();
    const { navigate, displayState } = useSearchState();
    const anchorRef = useRef(null);
    const [open, setOpen] = useState(false);
    const items = useMemo(() => sorters.options.map((option) => ({ id: option.id, label: localized(option.label), a11yLabel: localized(option.a11yLabel) })), [sorters, localized]);
    const selected = items.find((item) => item.id === displayState.sort) ?? items[0];
    const close = useCallback(() => setOpen(false), []);
    const select = useCallback((id) => {
        setOpen(false);
        track("results.sort_changed", { from: displayState.sort, to: id });
        navigate((state) => ({ ...state, sort: id, page: 0 }), "sort");
    }, [navigate, track, displayState.sort]);
    return (
        <div className={styles.sortBar}>
            <button ref={anchorRef} type="button" className={styles.sortButton} aria-haspopup="menu" aria-expanded={open} onClick={() => setOpen(!open)} data-testid="sorters-dropdown-trigger">
                <Icon name="sort" size="small" />
                <span>{t("sr.sort_by", { label: selected.label })}</span>
                <Icon name="chevron-down" size="small" />
            </button>
            <Popover open={open} anchorRef={anchorRef} onClose={close} closeLabel={t("sr.close")} testId="sorters-dropdown">
                <ListMenu items={items} selected={selected.id} onSelect={select} label={t("sr.sort_title")} />
            </Popover>
        </div>
    );
}
