import { useEffect, useState } from "react";
import { useQuery } from "@apollo/client";
import { Avatar, Button, Chip, IconButton, Inline, ReviewScore, Skeleton, Stack, Text } from "@kit/index.js";
import { LocalizedText, Translate, emitStepEvent, useExperimentTracking, useLocalized, useTranslation } from "travel-platform";
import { PROPERTY_PAGE_QUERY, PROPERTY_REVIEWS_QUERY } from "../queries.js";
import styles from "./Islands.module.css";

function SubscoreBar({ subscore }) {
    const localized = useLocalized();
    return (
        <li className={styles.subscore}>
            <div className={styles.subscoreLabel}>
                <span><LocalizedText value={subscore.name} /></span>
                <span className={styles.subscoreValue}>{subscore.formatted}</span>
            </div>
            <div className={styles.bar} aria-hidden="true">
                <span className={subscore.highlighted ? styles.barFillHigh : styles.barFill} style={{ "--travel_bar": `${subscore.value * 10}%` }} />
            </div>
        </li>
    );
}

function Topics({ topics }) {
    const t = useTranslation();
    const localized = useLocalized();
    const [selected, setSelected] = useState(null);
    return (
        <Stack gap={2}>
            <Text variant="strong_2"><Translate id="pp.topics" /></Text>
            <Inline gap={2} wrap>
                {topics.map((topic) => (
                    <button key={topic.id} type="button" className={styles.topic} aria-pressed={selected === topic.id} onClick={() => setSelected(selected === topic.id ? null : topic.id)} title={t("pp.mentions", { count: topic.mentions })}>
                        <Chip selected={selected === topic.id}>+ {localized(topic.label)}</Chip>
                    </button>
                ))}
            </Inline>
        </Stack>
    );
}

function ReviewCard({ review, visible }) {
    const t = useTranslation();
    const localized = useLocalized();
    return (
        <li className={visible ? styles.reviewCard : styles.reviewCardOffscreen} aria-hidden={!visible} data-testid="review-card">
            <div className={styles.reviewAuthor}>
                <Avatar name={review.author.name} initial={review.author.initial} />
                <div>
                    <Text variant="strong_2">{review.author.name}</Text>
                    <Text variant="small_1" color="alt">{review.author.countryCode.toUpperCase()} · {localized(review.author.travellerType)}</Text>
                </div>
                <span className={styles.reviewScore}>{review.scoreFormatted}</span>
            </div>
            <Text variant="strong_2"><LocalizedText value={review.title} /></Text>
            <Text variant="body_2" clamp={3}><span className={styles.liked}><Translate id="pp.liked" />: </span><LocalizedText value={review.positive} /></Text>
            {review.negative ? <Text variant="body_2" clamp={2} color="alt"><span className={styles.disliked}><Translate id="pp.disliked" />: </span><LocalizedText value={review.negative} /></Text> : null}
            <Text variant="small_1" color="alt">{t("pp.stayed", { room: review.stayed.roomName, nights: review.stayed.nights, month: localized(review.stayed.month) })}</Text>
            <Text variant="small_1" color="alt">{t("pp.helpful", { count: review.helpfulVotes })}</Text>
        </li>
    );
}

function ReviewCarousel({ propertyId }) {
    const t = useTranslation();
    const [start, setStart] = useState(0);
    const { data, loading } = useQuery(PROPERTY_REVIEWS_QUERY, { variables: { id: propertyId, page: 0, pageSize: 10, sort: "MOST_RELEVANT" }, ssr: false });
    useEffect(() => {
        if (!loading && data)
            emitStepEvent("property-island-ready", { island: "reviews" });
    }, [loading, data]);
    if (!data)
        return <Inline gap={3} aria-label={t("pp.loading_reviews")}><Skeleton width={280} height={180} /><Skeleton width={280} height={180} /><Skeleton width={280} height={180} /></Inline>;
    const reviews = data.propertyReviews.reviews;
    return (
        <div className={styles.carousel}>
            <IconButton icon="chevron-left" label={t("pp.previous")} variant="secondary" disabled={start === 0} onClick={() => setStart(Math.max(0, start - 3))} />
            <ul className={styles.reviewList}>
                {reviews.map((review, i) => <ReviewCard key={review.id} review={review} visible={i >= start && i < start + 3} />)}
            </ul>
            <IconButton icon="chevron-right" label={t("pp.next")} variant="secondary" disabled={start + 3 >= reviews.length} onClick={() => setStart(Math.min(reviews.length - 3, start + 3))} />
        </div>
    );
}

export function ReviewsIsland({ variables }) {
    const t = useTranslation();
    const localized = useLocalized();
    const { data } = useQuery(PROPERTY_PAGE_QUERY, { variables, fetchPolicy: "cache-only" });
    const property = data?.property;
    useExperimentTracking(property?.tracking);
    if (!property)
        return null;
    const summary = property.reviewSummary;
    return (
        <section className={styles.reviews} id="reviews" data-testid="reviews-island">
            <Inline gap={4} justifyContent="between">
                <Text as="h2" variant="headline_2"><Translate id="pp.reviews_title" /></Text>
                <Button variant="primary"><Translate id="pp.read_all" /></Button>
            </Inline>
            <ReviewScore score={summary.scoreFormatted} word={localized(summary.word)} count={localized(summary.countText)} size="large" />
            <Text variant="strong_2"><Translate id="pp.categories" /></Text>
            <ul className={styles.subscores}>{summary.subscores.map((s) => <SubscoreBar key={s.key} subscore={s} />)}</ul>
            <Topics topics={summary.topics} />
            <ReviewCarousel propertyId={property.id} />
        </section>
    );
}
