import { memo, useCallback, useMemo, useRef, useState } from "react";
import { Stack } from "@kit/index.js";
import { ErrorBoundary, TrackingScope, useExperimentTracking, useImpression, useTrack } from "travel-platform";
import { CardContext } from "./CardContext.js";
import { CardMedia } from "./CardMedia.jsx";
import { CardHeader } from "./CardHeader.jsx";
import { CardLocation } from "./CardLocation.jsx";
import { CardBadges } from "./CardBadges.jsx";
import { CardUnits } from "./CardUnits.jsx";
import { CardHighlights } from "./CardHighlights.jsx";
import { CardReview } from "./CardReview.jsx";
import { CardPrice } from "./CardPrice.jsx";
import { CardCta } from "./CardCta.jsx";
import { UnitDetails } from "./UnitDetails.jsx";
import { CardSection } from "./CardSection.jsx";
import styles from "./PropertyCard.module.css";

function useCardTracking(card, index) {
    const track = useTrack();
    return useCallback((name, payload) => track(name, { propertyId: card.id, position: index, ...payload }), [track, card.id, index]);
}

export const PropertyCard = memo(function PropertyCard({ card, index }) {
    const ref = useRef(null);
    const trackCard = useCardTracking(card, index);
    const [detailsOpen, setDetailsOpen] = useState(false);
    useImpression(ref, `card:${card.id}:${card.position}`, { propertyId: card.id, position: card.position });
    useExperimentTracking(card.tracking);
    const value = useMemo(() => ({ card, index, trackCard, detailsOpen, setDetailsOpen }), [card, index, trackCard, detailsOpen]);
    return (
        <ErrorBoundary name="property-card">
            <TrackingScope surface="property-card">
                <CardContext.Provider value={value}>
                    <article ref={ref} className={styles.card} data-testid="property-card" data-property-id={card.id} aria-label={card.a11y.label.text}>
                        <CardSection name="media"><CardMedia /></CardSection>
                        <div className={styles.body}>
                            <Stack gap={2} className={styles.main}>
                                <CardHeader />
                                <CardLocation />
                                <CardBadges />
                                <CardSection name="units"><CardUnits /></CardSection>
                                <CardHighlights />
                            </Stack>
                            <Stack gap={3} alignItems="end" justifyContent="between" className={styles.side}>
                                <CardSection name="review"><CardReview /></CardSection>
                                <CardSection name="price"><CardPrice /></CardSection>
                                <CardCta />
                            </Stack>
                        </div>
                        {detailsOpen ? <UnitDetails /> : null}
                    </article>
                </CardContext.Provider>
            </TrackingScope>
        </ErrorBoundary>
    );
});
