// The first-party event tracker: events are built as JSON objects, batched,
// serialized and handed to a sink in a task after the interaction, like the
// reference site's multitrack and sink endpoints. The sink drops the
// payload: the workload never touches the network.
import { isServer } from "../env.js";
import { now } from "../clock.js";

const CHANNELS = ["multitrack", "sink", "exposed", "squeak", "spans"];

class EventTracker {
    #queues = new Map(CHANNELS.map((channel) => [channel, []]));
    #sequence = 0;
    #scheduled = false;
    #page = null;
    #sent = { batches: 0, bytes: 0 };

    setPageContext(page) {
        this.#page = page;
    }

    get sent() {
        return this.#sent;
    }

    push(channel, name, payload) {
        if (isServer)
            return;
        this.#queues.get(channel).push({ name, seq: ++this.#sequence, ts: now() + this.#sequence, payload });
        this.#schedule();
    }

    track(name, payload) {
        this.push("multitrack", name, payload);
    }

    #schedule() {
        if (this.#scheduled)
            return;
        this.#scheduled = true;
        setTimeout(() => {
            this.#scheduled = false;
            this.flush();
        }, 0);
    }

    flush() {
        for (const [channel, queue] of this.#queues) {
            if (!queue.length)
                continue;
            const body = JSON.stringify({ channel, page: this.#page, events: queue.splice(0) });
            sink(channel, body);
            this.#sent.batches++;
            this.#sent.bytes += body.length;
        }
    }
}

let lastPayload = null;

function sink(channel, body) {
    lastPayload = new Blob([body], { type: "application/json" });
}

export function lastSinkPayload() {
    return lastPayload;
}

export const tracker = new EventTracker();
