import { memo } from "react";
import { Icon, Inline, Text } from "@kit/index.js";
import { LocalizedText, useExperiment, useLocalized, useTranslation } from "travel-platform";
import { useCard } from "./CardContext.js";
import styles from "./PropertyCard.module.css";

function MemberDeal({ deal }) {
    return (
        <Inline gap={1} className={styles.memberDeal}>
            <Icon name="sparkle" size="small" color="brand" />
            <Text as="span" variant="small_1"><LocalizedText value={deal.text} /></Text>
        </Inline>
    );
}

const Highlight = memo(function Highlight({ highlight }) {
    const localized = useLocalized();
    return (
        <li className={styles.highlight}>
            <span className={styles.tick} aria-hidden="true" />
            <Text as="span" variant="small_1">{localized(highlight.text)}</Text>
        </li>
    );
});

export function CardHighlights() {
    const { card } = useCard();
    const t = useTranslation();
    const showMemberDeal = useExperiment("sr_member_deal_badge") !== 2;
    return (
        <>
            {card.highlights.length ? (
                <ul className={styles.highlights} aria-label={t("sr.includes")}>
                    {card.highlights.map((highlight) => <Highlight key={highlight.id} highlight={highlight} />)}
                </ul>
            ) : null}
            {card.memberDeal && showMemberDeal ? <MemberDeal deal={card.memberDeal} /> : null}
        </>
    );
}
