import { LocalizedText, RemoteComponent } from "travel-platform";
import { Inline, Skeleton, Text } from "@kit/index.js";
import { useResults } from "./ResultsContext.js";
import { SortBar } from "./SortBar.jsx";
import { ViewToggle } from "./ViewToggle.jsx";
import styles from "./Results.module.css";

export function ResultsHeader() {
    const { result, loading } = useResults();
    return (
        <div className={styles.header}>
            {loading || !result ? <Skeleton width={320} height={28} /> : <Text as="h1" variant="headline_2" aria-live="polite" data-testid="results-title"><LocalizedText value={result.meta.title} /></Text>}
            <RemoteComponent module="merchBanners/SignInBanner" />
            <RemoteComponent module="filters/AppliedFilters" props={{ filters: result?.appliedFilters }} />
            <Inline gap={2} justifyContent="between">
                {result ? <SortBar sorters={result.sorters} /> : null}
                <ViewToggle />
            </Inline>
        </div>
    );
}
