import { PureComponent, useMemo } from "react";
import styles from "./Badge.module.css";
import { Icon } from "./Icon.jsx";
import { cx, useKitRoot } from "./util.js";

export function Badge({ variant = "neutral", emphasis = "subtle", icon, children, className, mixin, ...rest }) {
    const root = useKitRoot([styles.badge, styles[variant], styles[emphasis]], mixin, className);
    return (
        <span {...root} {...rest}>
            {icon ? <Icon name={icon} size="smaller" /> : null}
            <BadgeText>{children}</BadgeText>
        </span>
    );
}

function BadgeText({ children, nowrap = true }) {
    const className = useMemo(() => cx(styles.text, !nowrap && styles.wrap), [nowrap]);
    return <span className={className}>{children}</span>;
}

export function Chip({ selected, onDismiss, dismissLabel, children, testId }) {
    return (
        <span className={cx(styles.chip, selected && styles.selected)} data-testid={testId}>
            <span className={styles.text}>{children}</span>
            {onDismiss ? (
                <button type="button" className={styles.dismiss} aria-label={dismissLabel} onClick={onDismiss}>
                    <Icon name="close" size="smaller" />
                </button>
            ) : null}
        </span>
    );
}

// The star or square rating: a legacy class component of the kit.
export class Rating extends PureComponent {
    render() {
        const { value, symbol = "STARS", label, size = "small" } = this.props;
        const icons = [];
        for (let i = 0; i < value; i++)
            icons.push(<Icon key={i} name={symbol === "SQUARES" ? "square" : "star"} size={size} color="star" />);
        return <span className={cx(styles.rating, symbol === "SQUARES" && styles.squares)} role="img" aria-label={label}>{icons}</span>;
    }
}

function ScoreBadge({ score, size }) {
    const className = useMemo(() => cx(styles.score, styles[`score_${size}`]), [size]);
    return <div className={className} aria-label={`Scored ${score}`}>{score}</div>;
}

function ScoreText({ word, count, align = "start" }) {
    const className = useMemo(() => cx(styles.reviewText, align === "end" && styles.reviewTextEnd), [align]);
    return (
        <div className={className}>
            {word ? <div className={styles.word}>{word}</div> : null}
            {count ? <div className={styles.count}>{count}</div> : null}
        </div>
    );
}

export function ReviewScore({ score, word, count, size = "medium", layout = "inline", testId }) {
    return (
        <div className={cx(styles.review, styles[`layout_${layout}`])} data-testid={testId}>
            <ScoreBadge score={score} size={size} />
            <ScoreText word={word} count={count} />
        </div>
    );
}
